import { ReactNode, useEffect, useState } from 'react';

import { fireEvent, render } from '@testing-library/react';

import { Button } from '../button';
import ModalTwo from './Modal';

// Mocked so that the modal renders in the same container
jest.mock('react-dom', () => {
    const original = jest.requireActual('react-dom');
    return {
        ...original,
        createPortal: (node: any) => node,
    };
});

const Inner = ({ onMount }: { onMount: () => void }) => {
    useEffect(() => {
        onMount();
    }, []);
    return <div data-testid="inner">I'm only mounted once</div>;
};

const MyModal = ({
    open,
    onClose,
    children,
    disableCloseOnEscape,
}: {
    open: boolean;
    onClose: () => void;
    children: ReactNode;
    disableCloseOnEscape?: boolean;
}) => {
    return (
        <ModalTwo open={open} onClose={onClose} disableCloseOnEscape={disableCloseOnEscape}>
            {children}
            <Button data-testid="close-button" onClick={onClose} />
        </ModalTwo>
    );
};

const Container = ({
    children,
    open: initialOpen = false,
    disableCloseOnEscape,
}: {
    children: ReactNode;
    open?: boolean;
    disableCloseOnEscape?: boolean;
}) => {
    const [open, setOpen] = useState(initialOpen);
    return (
        <>
            <Button data-testid="open-button" onClick={() => setOpen(true)} />
            <MyModal open={open} onClose={() => setOpen(false)} disableCloseOnEscape={disableCloseOnEscape}>
                {children}
            </MyModal>
        </>
    );
};

const getOutModal = (container: Element) => {
    return container.querySelector('.modal-two--out');
};
const maybeTriggerOutAnimation = (div?: Element | null) => {
    if (!div) {
        return;
    }
    fireEvent.animationEnd(div, { animationName: 'anime-modal-two-out' });
};

describe('ModalTwo rendering', () => {
    it('should not render children when closed', () => {
        const { queryByTestId } = render(
            <ModalTwo>
                <div data-testid="inner">Not rendered</div>
            </ModalTwo>
        );
        expect(queryByTestId('inner')).toBeNull();
    });

    it('should render children when open', () => {
        const { queryByTestId } = render(
            <ModalTwo open>
                <div data-testid="inner">Rendered</div>
            </ModalTwo>
        );
        expect(queryByTestId('inner')).toHaveTextContent('Rendered');
    });

    it('should render children when going from closed to open', () => {
        const { getByTestId, queryByTestId } = render(
            <Container>
                <div data-testid="inner">Rendered</div>
            </Container>
        );
        expect(queryByTestId('inner')).toBeNull();
        fireEvent.click(getByTestId('open-button'));
        expect(queryByTestId('inner')).toHaveTextContent('Rendered');
    });

    it('should not render children when going from open to closed', () => {
        const { container, getByTestId, queryByTestId } = render(
            <Container open>
                <div data-testid="inner">Rendered</div>
            </Container>
        );
        expect(getOutModal(container)).toBeNull();
        expect(queryByTestId('inner')).toHaveTextContent('Rendered');
        fireEvent.click(getByTestId('close-button'));
        maybeTriggerOutAnimation(getOutModal(container));
        expect(queryByTestId('inner')).toBeNull();
    });

    it('should only trigger mount once per render', async () => {
        const handleMount = jest.fn();
        const { container, getByTestId, queryByTestId } = render(
            <Container>
                <Inner onMount={handleMount} />
            </Container>
        );

        const run = (n: number) => {
            expect(getOutModal(container)).toBeNull();
            expect(handleMount).toHaveBeenCalledTimes(n);
            expect(queryByTestId('inner')).toBeNull();

            fireEvent.click(getByTestId('open-button'));
            expect(getOutModal(container)).toBeNull();
            expect(handleMount).toHaveBeenCalledTimes(n + 1);
            expect(queryByTestId('inner')).toHaveTextContent('mounted once');

            fireEvent.click(getByTestId('close-button'));
            maybeTriggerOutAnimation(getOutModal(container));
            expect(queryByTestId('inner')).toBeNull();
            expect(handleMount).toHaveBeenCalledTimes(n + 1);
        };

        run(0);
        run(1);
        run(2);
    });

    it('should only trigger mount once per render if initially opened', async () => {
        const handleMount = jest.fn();
        const { container, getByTestId, queryByTestId } = render(
            <Container open={true}>
                <Inner onMount={handleMount} />
            </Container>
        );

        const run = (n: number) => {
            expect(getOutModal(container)).toBeNull();
            expect(handleMount).toHaveBeenCalledTimes(n);
            expect(queryByTestId('inner')).toHaveTextContent('mounted once');

            fireEvent.click(getByTestId('close-button'));
            maybeTriggerOutAnimation(getOutModal(container));
            expect(queryByTestId('inner')).toBeNull();
            expect(handleMount).toHaveBeenCalledTimes(n);

            fireEvent.click(getByTestId('open-button'));
            expect(getOutModal(container)).toBeNull();
            expect(handleMount).toHaveBeenCalledTimes(n + 1);
            expect(queryByTestId('inner')).toHaveTextContent('mounted once');
        };

        run(1);
        run(2);
        run(3);
    });
});

describe('ModalTwo Hotkeys', () => {
    it('should close on esc', () => {
        const { container, getByTestId, queryByTestId } = render(
            <Container open={true}>
                <div data-testid="inner">Rendered</div>
            </Container>
        );
        expect(getOutModal(container)).toBeNull();
        expect(queryByTestId('inner')).toHaveTextContent('Rendered');
        fireEvent.keyDown(getByTestId('close-button'), { key: 'Escape' });
        maybeTriggerOutAnimation(getOutModal(container));
        expect(queryByTestId('inner')).toBeNull();
    });

    it('should not close on esc if disabled', () => {
        const { container, getByTestId, queryByTestId } = render(
            <Container open={true} disableCloseOnEscape>
                <div data-testid="inner">Rendered</div>
            </Container>
        );
        expect(getOutModal(container)).toBeNull();
        expect(queryByTestId('inner')).toHaveTextContent('Rendered');
        fireEvent.keyDown(getByTestId('close-button'), { key: 'Escape' });
        maybeTriggerOutAnimation(getOutModal(container));
        expect(queryByTestId('inner')).toHaveTextContent('Rendered');
    });
});
import { ComponentType, useRef, useState } from 'react';

import noop from '@proton/utils/noop';

import useModalState from './useModalState';

export const useModalTwo = function <OwnProps, Value>(
    Modal: ComponentType<any>,
    usePromise = true
): [JSX.Element | null, (ownProps: OwnProps) => Promise<Value>] {
    const [props, setOpen, render] = useModalState();
    const [ownProps, setOwnProps] = useState<OwnProps>();
    const promiseRef = useRef<{
        promise: Promise<Value>;
        resolve: (value: Value) => void;
        reject: (reason?: any) => void;
    }>();

    const createPromise = () => {
        let resolve: (value: Value) => void = noop;
        let reject: (reason?: any) => void = noop;
        const promise = new Promise<Value>((res, rej) => {
            resolve = res;
            reject = rej;
        });
        promiseRef.current = { promise, resolve, reject };
        return promise;
    };

    const handleShowModal = (ownProps: OwnProps) => {
        setOwnProps(ownProps);
        setOpen(true);
        return createPromise();
    };

    const handleResolve = (value: Value) => {
        promiseRef.current?.resolve(value);
        props.onClose();
    };

    const handleReject = (reason?: any) => {
        promiseRef.current?.reject(reason);
        props.onClose();
    };

    const promiseHandlers = usePromise ? { onResolve: handleResolve, onReject: handleReject } : {};

    const modal = render ? <Modal {...props} {...ownProps} {...promiseHandlers} /> : null;

    return [modal, handleShowModal];
};

import { useEffect, useLayoutEffect, useRef } from 'react';

import PropTypes from 'prop-types';

import { dialogRootClassName } from '@proton/shared/lib/busy';

import { classnames } from '../../helpers';
import { useHotkeys } from '../../hooks';
import { useFocusTrap } from '../focus';
import { useModalPosition } from '../modalTwo/modalPositions';
import Portal from '../portal/Portal';

const CLASSES = {
    MODAL: 'modal',
    MODAL_IN: 'modal--in',
    MODAL_OUT: 'modal--out',
    MODAL_INTERMEDIATE: 'modal--intermediate',
    MODAL_SMALL: 'modal--smaller',
    MODAL_TINY: 'modal--tiny',
};

const ANIMATIONS = {
    MODAL_IN: 'anime-modal-in',
    MODAL_OUT: 'anime-modal-out',
};

/**
 * @deprecated Please use ModalTwo instead
 * @type any
 */
const Dialog = ({
    onClose,
    onEnter,
    onExit,
    intermediate: isIntermediate = false,
    small: isSmall = false,
    tiny: isTiny = false,
    isClosing = false,
    modalTitleID,
    children,
    className: extraClassNames = '',
    disableCloseOnOnEscape,
    open, // To prevent it being passed in rest
    ...rest
}) => {
    const rootRef = useRef(null);
    const hasCalledExit = useRef(false);
    const hasCalledClose = useRef(false);
    const focusTrapProps = useFocusTrap({ rootRef });
    const last = useModalPosition(true);

    useLayoutEffect(() => {
        hasCalledClose.current = isClosing;
    }, [isClosing]);

    useEffect(() => {
        return () => {
            // Safety measure to make sure cleanup functions always get called, even if the component gets forcefully removed
            if (!hasCalledClose.current) {
                onClose?.();
            }
            if (!hasCalledExit.current) {
                onExit?.();
            }
        };
    }, []);

    useHotkeys(rootRef, [
        [
            'Escape',
            (e) => {
                if (!disableCloseOnOnEscape) {
                    e.stopPropagation();
                    onClose?.();
                }
            },
        ],
    ]);

    return (
        <Portal>
            <div className={classnames([dialogRootClassName, !last && 'is-behind-backdrop'])}>
                <dialog
                    aria-labelledby={modalTitleID}
                    aria-modal="true"
                    open
                    className={classnames([
                        CLASSES.MODAL,
                        isSmall && CLASSES.MODAL_SMALL,
                        isTiny && CLASSES.MODAL_TINY,
                        isIntermediate && CLASSES.MODAL_INTERMEDIATE,
                        (isSmall || isTiny || isIntermediate) && 'modal--shorter-labels',
                        isClosing && CLASSES.MODAL_OUT,
                        extraClassNames,
                        'outline-none',
                    ])}
                    onAnimationEnd={({ animationName }) => {
                        if (animationName === ANIMATIONS.MODAL_OUT && isClosing) {
                            hasCalledExit.current = true;
                            onExit?.();
                        }
                        if (animationName === ANIMATIONS.MODAL_IN && !isClosing) {
                            onEnter?.();
                        }
                    }}
                    {...rest}
                    ref={rootRef}
                    {...focusTrapProps}
                >
                    {children}
                </dialog>
            </div>
        </Portal>
    );
};

Dialog.propTypes = {
    onEnter: PropTypes.func,
    open: PropTypes.bool,
    onExit: PropTypes.func.isRequired,
    onClose: PropTypes.func.isRequired,
    children: PropTypes.node.isRequired,
    modalTitleID: PropTypes.string.isRequired,
    className: PropTypes.string,
    small: PropTypes.bool,
    isClosing: PropTypes.bool,
    disableCloseOnOnEscape: PropTypes.bool,
};

export default Dialog;
